sys_script_include.script:
var FleetReservationMonitor = Class.create();
FleetReservationMonitor.prototype = {
    // FLEET-38: Overdue Reservation Monitor (no-show release + D-14 overdue safety net)
    RES: 'x_1850693_enterp_0_reservation',

    initialize: function() {},

    /** Returns {noShows, overdue}. */
    run: function() {
        var result = { noShows: 0, overdue: 0 };
        var now = new GlideDateTime();

        // Not picked up within start + no_show.release_minutes -> NO_SHOW (D-02, D-03)
        var cutoff = new GlideDateTime();
        cutoff.addSeconds(-FleetConfig.get('no_show.release_minutes') * 60);
        var ns = new GlideRecord(this.RES);
        ns.addQuery('reservation_state', 'IN', 'ASSIGNED,READY_FOR_PICKUP');
        ns.addQuery('start_datetime', '<', cutoff.getValue());
        ns.query();
        while (ns.next()) {
            var res = new GlideRecord(this.RES);
            res.get(ns.getUniqueValue());
            res.setValue('reservation_state', 'NO_SHOW'); // task.active = false and vehicle sync via the reservation rules
            res.work_notes = 'Vehicle not picked up within ' + FleetConfig.get('no_show.release_minutes') +
                ' minutes of the start time - released as NO_SHOW by the Overdue Reservation Monitor.';
            if (res.update()) {
                gs.eventQueue('x_1850693_enterp_0.reservation.no_show', res, res.getValue('requested_by'), res.getValue('manager_approver'));
                result.noShows++;
            }
        }

        // D-14 safety net: ACTIVE trips past their end time (the precise setter is FLEET-51)
        var od = new GlideRecord(this.RES);
        od.addQuery('reservation_state', 'ACTIVE');
        od.addQuery('end_datetime', '<', now.getValue());
        od.addQuery('is_overdue', false);
        od.query();
        while (od.next()) {
            var o = new GlideRecord(this.RES);
            o.get(od.getUniqueValue());
            o.setValue('is_overdue', true);
            if (o.update()) {
                result.overdue++;
            }
        }

        if (result.noShows > 0) {
            new FleetWaitlist().process(); // released vehicles may serve waitlisted requests
        }
        return result;
    },

    type: 'FleetReservationMonitor'
};
